export function adminLoginHtml(): string {
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f4f0e7"><title>The Black Sheep Shop · Admin sign in</title>
<style>:root{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#171713;background:#f4f0e7}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 50% 20%,#fffdf9 0,#f4f0e7 52%,#eee6d7 100%)}.card{width:min(460px,100%);background:rgba(255,253,249,.95);border:1px solid #ded6c8;border-radius:22px;padding:28px;box-shadow:0 18px 50px rgba(40,31,19,.08)}.brand{display:flex;gap:10px;align-items:center;margin-bottom:26px}.mark{width:38px;height:38px;border-radius:13px;background:#171713;color:#fff;display:grid;place-items:center;font-family:Georgia,serif;font-weight:700}.brand-copy{font-family:Georgia,serif;font-size:19px;line-height:1}.eyebrow{color:#756f64;font-size:13px}h1{font-family:Georgia,serif;font-size:38px;line-height:1;margin:4px 0 10px}.muted{color:#756f64;line-height:1.45}.security{border:1px solid #e7dfd2;background:#faf6ed;border-radius:13px;padding:12px;margin:18px 0;font-size:12px;color:#655f56}button,input{font:inherit;width:100%;border-radius:12px;padding:13px}button{border:0;background:#171713;color:#fff;font-weight:800;cursor:pointer;margin-top:10px}input{border:1px solid #d5ccbc;background:#fff;margin-top:10px;letter-spacing:5px;font-size:22px;text-align:center;outline:none}input:focus{border-color:#9e927f;box-shadow:0 0 0 3px rgba(178,161,132,.14)}#verify{display:none}.status{min-height:24px;margin-top:12px;font-size:13px}.error{color:#9b1c1c}</style></head>
<body><main class="card"><div class="brand"><div class="mark">BS</div><div class="brand-copy">The Black<br>Sheep Shop</div></div><div class="eyebrow">Private owner dashboard</div><h1>Admin sign in</h1><p class="muted">A one-time security code will be sent to the configured owner email address.</p><div class="security">No password is stored here. Codes expire automatically and the admin session is protected by a secure, HTTP-only cookie.</div><button id="send">Send login code</button><div id="verify"><input id="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="000000"><button id="enter">Sign in</button></div><div id="status" class="status" aria-live="polite"></div></main>
<script>var status=document.getElementById('status'),verify=document.getElementById('verify');async function post(path,body){var r=await fetch(path,{method:'POST',headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined}),j=await r.json().catch(function(){return {}});if(!r.ok)throw new Error(j&&j.error&&j.error.message||'Request failed');return j}document.getElementById('send').onclick=async function(){status.className='status';status.textContent='Sending…';try{await post('/admin/auth/request');verify.style.display='block';status.textContent='Code sent. Check the owner email.';document.getElementById('code').focus()}catch(e){status.className='status error';status.textContent=e.message}};document.getElementById('enter').onclick=async function(){var code=document.getElementById('code').value.trim();status.className='status';status.textContent='Checking…';try{await post('/admin/auth/verify',{code:code});location.href='/admin#orders'}catch(e){status.className='status error';status.textContent=e.message}};document.getElementById('code').addEventListener('keydown',function(e){if(e.key==='Enter')document.getElementById('enter').click()});</script></body></html>`;
}
